local players = {}  minetest.register_chatcommand("rtp", {     description = "Random Teleport",     privs = {         interact = true,         teleport = true,     },     func = function(name)         local teleporting = false          for k, v in pairs(players) do             if v == name then                 teleporting = true                 break             end         end          if teleporting == false then             table.insert(players, name)                                    local player = minetest.get_player_by_name(name)               local old_pos = player:getpos()                                 local x = math.random(-30000, 30000)             local y = 0             local z = math.random(-30000, 30000)             local pos = vector.new(x, y, z)             local failed = false              player:setpos(pos)              minetest.chat_send_player(name, "Teleporting...")              minetest.after(3, function()                 local node_name = minetest.get_node(player:getpos())                 .name                                                                        while node_name ~= "air" do                     y = y + 1                     local pos = vector.new(x, y, z)                     player:setpos(pos)                     node_name = minetest.get_node(player:getpos()).name                      if y > 500 then                         player:setpos(old_pos)                         failed = true                         break                     end                 end                  if failed == true then                     minetest.chat_send_player(name,                         "Teleportation failed! Returned to " .. minetest.pos_to_string(player:getpos()) .. ".")                 else                     minetest.chat_send_player(name, "Teleported to " .. minetest.pos_to_string(player:getpos()) .. ".")                 end             end)              minetest.after(10, function()                 for k, v in pairs(players) do                     if v == name then                         table.remove(players, k)                         break                     end                 end             end)         else             minetest.chat_send_player(name, "Please wait a few seconds before using /rtp again.")         end     end, }) 